SELECT 'fb000000-0000-0000-0000-000000000052','fb000000-0000-0000-0000-000000000051',id,99,'internal','pending',1 FROM public.production_stages WHERE code<>'design' ORDER BY code LIMIT 1;
SELECT throws_ok($$UPDATE public.production_stage_runs SET status='in_progress' WHERE id='fb000000-0000-0000-0000-000000000052'$$,'23514','Design QC approval or permitted bypass required','Stage writer cannot skip the revision gate');
