INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-qc-files','fb000000-0000-0000-0000-000000000011/fb000000-0000-0000-0000-000000000027/execution.zip',jsonb_build_object('eTag','"'||lpad('21',32,'0')||'"','size',100,'mimetype','application/zip'));
