SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000027','https://files.example.test/reference-change-only','Same immutable files');
SELECT is((SELECT count(*) FROM public.design_qc_events WHERE id='fb000000-0000-0000-0000-000000000027'),1::bigint,'Unchanged-file retry records one submission event');
SELECT lives_ok($$UPDATE public.orders SET instructions='technical note',design_price=100 WHERE case_id='QC-CASE'$$,'Non-file changes retain approval');
SELECT public.release_design_revision('fb000000-0000-0000-0000-000000000011');
SELECT lives_ok($$UPDATE public.production_stage_runs SET status='in_progress' WHERE id='fb000000-0000-0000-0000-000000000052'$$,'Approved files can start a production stage');
SELECT is((SELECT design_revision_id FROM public.production_stage_runs WHERE id='fb000000-0000-0000-0000-000000000052'),'fb000000-0000-0000-0000-000000000021'::uuid,'Started work snapshots the approved revision');
UPDATE public.external_work_orders SET status='sent' WHERE id='fb000000-0000-0000-0000-000000000058';
SELECT is((SELECT design_revision_id FROM public.external_work_orders WHERE id='fb000000-0000-0000-0000-000000000058'),'fb000000-0000-0000-0000-000000000021'::uuid,'External dispatch also snapshots the approved execution files');
SELECT is((SELECT production_status FROM public.orders WHERE case_id='QC-CASE'),'in_production','Approved revision can enter execution');
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000022','https://files.example.test/package','updated files without preview');
SELECT is(public.get_stage_design_execution_path('fb000000-0000-0000-0000-000000000052'),'fb000000-0000-0000-0000-000000000011/fb000000-0000-0000-0000-000000000021/execution.zip','Existing stage downloads its exact snapshot after later files arrive');
SELECT throws_ok($$SELECT public.decide_design_revision('fb000000-0000-0000-0000-000000000021',gen_random_uuid(),'approved','')$$,'23514','Review the current revision','Stale review cannot approve a newer revision');
