WITH changed AS (UPDATE storage.objects SET metadata='{}' WHERE bucket_id='design-qc-files' RETURNING id) SELECT is(count(*),0::bigint,'Even a file owner cannot overwrite immutable stored assets') FROM changed;
SELECT throws_like($$DELETE FROM storage.objects WHERE bucket_id='design-qc-files'$$,'%Direct deletion from storage tables is not allowed%','Operational SQL cannot delete stored revision files');
