INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('design-qc-files','fb000000-0000-0000-0000-000000000011/fb000000-0000-0000-0000-000000000025/execution.zip',jsonb_build_object('eTag','"'||lpad('25',32,'0')||'"','size',100,'mimetype','application/zip'));
SELECT public.submit_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000025','https://files.example.test/replacement-work','Replacement completed work');
