SELECT set_config('request.jwt.claim.sub','fb000000-0000-0000-0000-000000000001',true);
SELECT public.reassign_design_revision('fb000000-0000-0000-0000-000000000011','fb000000-0000-0000-0000-000000000003','Second handoff, default fee',30,NULL,'fb000000-0000-0000-0000-000000000043');
