SELECT is((SELECT count(*) FROM public.financial_obligations f JOIN public.design_qc_assignments a ON a.id=f.design_qc_assignment_id WHERE a.order_id='fb000000-0000-0000-0000-000000000011' AND f.status<>'void'),2::bigint,'Multiple former contributors retain separate explicit settlements');
SELECT public.apply_order_issue_transition_v2('fb000000-0000-0000-0000-000000000011','cancel_order','Cancel current unearned work',gen_random_uuid(),'zero');
