SELECT is((SELECT sum(f.net_amount) FROM public.financial_obligations f JOIN public.design_qc_assignments a ON a.id=f.design_qc_assignment_id WHERE a.order_id='fb000000-0000-0000-0000-000000000011' AND f.status<>'void'),110::numeric,'Current cancellation does not erase separately settled former work');
SELECT * FROM finish();
ROLLBACK;
